#' Plot X-13 seasonal adjustment (or trend) from the past and present
#'
#' Generates a \code{ggplot} object with a time series plot that compares an X-13 
#' seasonal adjustment (or trend), extracted from two \code{seas} objects: 
#' one from the past and one with added observations.
#'
#' Version 1.7, 2026-10-28
#'
#' @param seas_obj_past \code{seas} object for a single series generated by the
#'        \code{seasonal} package \insertCite{seasonal2018}{blsplotGG}.
#'        This is the initial seasonal adjustment. This is a required entry.
#' @param seas_obj_update \code{seas} object for a single series generated by the
#'        \code{seasonal} package \insertCite{seasonal2018}{blsplotGG}.
#'        This is the seasonal adjustment (or trend) for the first series plus 
#'        some additional observations. This is a required entry.
#' @param plot_trend Logical scalar, indicates if trend is plotted rather than the 
#'        seasonal adjustment. Default is \code{FALSE}.
#' @param main_title Title for the plot. 
#'        By default, the routine will generate a trend based on the 
#'        type of adjustment (X-11 and SEATS) done.
#' @param sub_title Subtitle for the plot. Optional entry.
#' @param this_x_label Label for X-axis.  Default is \code{"Time"}
#' @param this_y_label Label for Y-axis.  Default is \code{" "}
#' @param start_plot Integer vector of length 2; 
#'        Starting date for plot. Default is starting date for the time series. 
#' @param do_grid Logical scalar; indicates if certain plots will have grid lines. 
#'        Default is no grid lines. 
#' @param do_background Logical scalar; indicates grey background included in plot.
#'        Default is no grey background;
#' @param line_color Character vector of length 2 (if \code{plot_ori} is \code{FALSE})
#'        or 3 (if \code{plot_ori} is \code{TRUE}); color used for lines in the plot,
#'        in the order of original series (if specified), seasonally adjusted series, trend. 
#'        Default is generated from the \code{RColorBrewer} palette \code{"Dark2"}.
#'        For a listing of R color codes, 
#'        see \insertCite{rchartsColors;textual}{blsplotGG}.
#' @param this_palette Character string; default \code{RColorBrewer} palette \insertCite{RColorBrewer}{blsplotGG}.
#'        Deault is \code{"Dark2"}.
#' @param line_label Caracter vector of length 2; labels used for lines in the plot,
#'        in the order of original series, seasonally adjusted series. 
#'        Default is \code{c("Past Trend", "Updated Trend")} (if trend plotted) or
#'        \code{c("Past SA", "Updated SA")}.
#' @param this_legend_title Title for legend.  Default is \code{"Series"}
#' @param this_legend_title_size integer scalar; Size of the legend title.
#'        Must be greater than zero.
#'        Default is \code{12}.
#' @param this_legend_text_size integer scalar; Size of the legend title.
#'        Must be greater than zero.
#'        Default is \code{10}.
#' @param this_legend_position Character string; indicates the position of the plot legend.
#'        Possible values are \code{"right"}, \code{"left"}, \code{"top"}, 
#'        \code{"bottom"}, and \code{"none"}
#'        Default is \code{"right"}.
#' @param this_legend_space integer scalar; Space between legend and plot in points.
#'        Must be greater than or equal to zero.
#'        Default is \code{10}.
#' @return A \code{ggplot} object that generates a plot comparing a 
#'         seasonally adjusted series (or trend) for a base time frame and an
#'         updated time frame.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples
#' shoes_seas_2007 <- 
#'    seasonal::seas(shoes2007, 
#'      arima.model = "(0 1 1)(0 1 1)",
#'      regression.variables = c(
#'         "td", "easter[8]", 
#'         "AO1995.Feb", "LS2005.Feb", "AO2005.Mar"
#'      ),
#'      regression.aictest = NULL,
#'      transform.function = "log",
#'      forecast.maxlead = 60, 
#'      x11.seasonalma = "s3x3",
#'      outlier = NULL)
#' 
#' shoes_seas_2008 <- 
#'    seasonal::seas(shoes2008, 
#'      arima.model = "(0 1 1)(0 1 1)",
#'      regression.variables = c(
#'         "td", "easter[8]", 
#'         "AO1995.Feb", "LS2005.Feb", "AO2005.Mar"
#'      ),
#'      regression.aictest = NULL,
#'      transform.function = "log",
#'      forecast.maxlead = 60, 
#'      x11.seasonalma = "s3x3",
#'      outlier = NULL)
#'
#' shoes_2007_and_2008_sa_p <- 
#'    plot_sadj_update(
#'       shoes_seas_2007, shoes_seas_2008,
#'       start_plot = c(2004,1),
#'       main_title = "US Shoe Sates, 2007 and 2008",
#'       sub_title = "SEATS Seasonal Adjustment",
#'       line_color = c("steelblue", "forestgreen"))
#'
#' @importFrom rlang .data
#' @importFrom magrittr %>%
#' @importFrom Rdpack reprompt
#' @export
plot_sadj_update <- 
    function(seas_obj_past = NULL, 
             seas_obj_update = NULL, 
			 plot_trend = FALSE,
             main_title = NULL, 
             sub_title = NULL, 
             this_x_label = "Time", 
             this_y_label = " ", 
             start_plot = NULL, 
             do_grid = FALSE,
             do_background = FALSE,
             line_color = NULL, 
             this_palette = "Dark2",
             line_label = NULL,
             this_legend_title = "Series",
			 this_legend_title_size = 12,
			 this_legend_text_size = 10,
			 this_legend_position = "right",
			 this_legend_space = 10) {
    # Author: Brian C. Monsell (OEUS) Version 1.7, 2026-10-28

    # check if a value is specified for \code{seas_obj_past}
    if (is.null(seas_obj_past)) {
        cat("must specify a seas object for seas_obj_past")
		return(NULL)
    } else {
    # check if a seas object is specified for \code{seas_obj_past}
        if (!inherits(seas_obj_past, "seas")) {
            cat("First argument must be a seas object")
			return(NULL)
        }
    }

    # check if a value is specified for \code{seas_obj_update}
    if (is.null(seas_obj_update)) {
        cat("must specify a seas object for seas_obj_update")
		return(NULL)
    } else {
    # check if a seas object is specified for \code{seas_obj_update}
        if (!inherits(seas_obj_update, "seas")) {
            cat("Second argument must be a seas object")
			return(NULL)
        }
    }

	# check legend options 
	position_all <- c("top", "bottom", "left", "right")
	if (sum(match(position_all, this_legend_position), na.rm = TRUE) == 0) {
        cat(paste("Legend position choice not valid:", this_legend_position))
		return(NULL)
	}
	
    # check if values of \code{this_legend_text_size}, \code{this_legend_title_size}, 
	# and \code{this_legend_space} are valid, return \code{NULL} if not.
	if (this_legend_text_size <= 0) {
        cat(paste("Legend text size not valid (must be greater than zero):", 
		           this_legend_text_size))
        return(NULL)
	}
	
	if (this_legend_title_size <= 0) {
        cat(paste("Legend title text size not valid (must be greater than zero):", 
		           this_legend_title_size))
        return(NULL)
	}
	
	if (this_legend_space < 0) {
        cat(paste("Legend space size not valid (must be greater than or equal to zero):", 
		           this_legend_space))
        return(NULL)
	}
	
	# extract trend or seasonal adjustment
	if (plot_trend) {
		this_past   <- seasonal::trend(seas_obj_past)
		this_update <- seasonal::trend(seas_obj_update)
	} else {
		this_past   <- seasonal::final(seas_obj_past)
		this_update <- seasonal::final(seas_obj_update)
	}
	
    # If \code{start_plot) specified, shorten series
	this_freq    <- frequency(this_update)
    if (!is.null(start_plot)) {
        this_past   <- window(this_past,   start = start_plot)
        this_update <- window(this_update, start = start_plot)
		this_start <- start_plot
    } else {
		# check if start of series are the same
		start_past   <- start(this_past)
		start_update <- start(this_update)
	
		same_start <- compare_dates(start_past, start_update)
	# if starting dates are not the same, augment series with NAs 
	# so that the series start on the same date.
		if (same_start) {
			this_start <- start_update
		} else {
			diff_start <- 
				difference_dates(start_past, start_update) - 1
			if (diff_start > 0) { 
				this_start <- start_past
				this_update <- 
					ts(c(rep(NA, diff_start), this_update),
						start = this_start, frequency = this_freq)
			} else {
				this_start <- start_update
				this_past  <-
					ts(c(rep(NA, abs(diff_start)), this_past),
						start = this_start, frequency = this_freq)
			}
		}
	}
	
	# get end of series
	end_past   <- end(this_past)
	end_update <- end(this_update)
	same_end <- compare_dates(end_past, end_update)
	
	# check if the end of the series are the same
	if (same_end) {
        cat("End dates should not be the same for both adjustments")
		return(NULL)
	} 
	
	# check if the end of the updated is before the end of the past series
	diff_end <- 
		difference_dates(end_past, end_update) - 1
		
	# get end of series
	if (diff_end < 0) {
        cat("End date for updated adjustment should be after the end date for past adjustment.")
		return(NULL)
	} 
	
	this_past <- ts(c(this_past, rep(NA, diff_end)), 
					start = this_start, frequency = this_freq)

	# Get and check seasonal adjustment types
	if ("seatsadj" %in% names(seasonal::udg(seas_obj_past))) {
		this_sa_type_past <- "SEATS"
	} else {
		this_sa_type_past <- "X-11"
	}
	if ("seatsadj" %in% names(seasonal::udg(seas_obj_update))) {
		this_sa_type_update <- "SEATS"
	} else {
		this_sa_type_update <- "X-11"
	}
	
	if (this_sa_type_past != this_sa_type_update) {
        cat("Seasonal adjustment type should be the same for both adjustments")
		return(NULL)
	}

	# Generate main title if not specified
	if (is.null(main_title)) {
		if (plot_trend) {
			main_title <- 
				paste0(this_sa_type_update, " Trend")
		} else {
			main_title <- 
				paste0(this_sa_type_update, " Seasonal Adjutment")
		}
	}
	
	# check legend options 
	position_all <- c("top", "bottom", "left", "right")
	if (sum(match(position_all, this_legend_position), na.rm = TRUE) == 0) {
        cat(paste("Legend position choice not valid:", this_legend_position))
		return(NULL)
	}
	
	if (this_legend_text_size <= 0) {
        cat(paste("Legend text size not valid (must be greater than zero):", 
		           this_legend_text_size))
		return(NULL)
	}
	
	if (this_legend_title_size <= 0) {
        cat(paste("Legend title text size not valid (must be greater than zero):", 
		           this_legend_title_size))
		return(NULL)
	}
	
	# Generate line labels, color
	num_color <- 2
	if (is.null(line_label)) { 
		if (plot_trend) {
			line_label <- c("Past Trend", "Updated Trend")
		} else {
			line_label <- c("Past SA", "Updated SA")
		}
	}

    if (is.null(line_color)) {
        line_color <- RColorBrewer::brewer.pal(3, this_palette)[1:num_color]
    } else {
        if (length(line_color) < num_color) {
            warning("Number of line colors specified less than series plotted.")
            warning("Will use default palette to increase number of colors.")
            line_color <- RColorBrewer::brewer.pal(3, this_palette)[1:num_color]
        }
    }

	# create data frame for plot
    this_df <- 
		data.frame(date = tsbox::ts_df(this_update)$time, 
			past = as.double(this_past), 
			update = as.double(this_update)) %>%
			dplyr::select(.data$date, .data$past, .data$update) %>%
			tidyr::gather(key = "comp", value = "value", -date)
    
	# generate plot object
	p_update <- 
        ggplot2::ggplot(this_df) + 
        ggplot2::geom_line(ggplot2::aes(x = .data$date, 
                                        y = .data$value, 
                                        color = .data$comp)) + 
        ggplot2::scale_color_manual(labels = line_label, 
                                        values = line_color) +
        ggplot2::labs(title = main_title,
                      subtitle = sub_title,
                      x = this_x_label,
                      y = this_y_label)
    p_update <- 
		p_update + 
			ggplot2::guides(color = ggplot2::guide_legend(this_legend_title))
	
	# remove grey background if \code{do_background = FALSE} 
    if (!do_background) {
		p_update <- p_update + ggplot2::theme_bw()
    }

	# remove grid lines if \code{do_grid = FALSE}
	if (!do_grid) {
	    p_update <- p_update + 
		    ggplot2::theme(panel.grid.major = ggplot2::element_blank(), 
			               panel.grid.minor = ggplot2::element_blank())
	}

	# Add legend
	p_update <- p_update +
		ggplot2::theme(legend.text = ggplot2::element_text(size = this_legend_text_size),
		               legend.title = ggplot2::element_text(size = this_legend_title_size),
					   legend.position = this_legend_position,
					   legend.box.spacing = ggplot2::unit(this_legend_space, "pt"))
       
	return(p_update)

}